var i=`0131-kharcho`;var n=`world-0131`;var a=`GE`;var s=`western-asia`;var o=4;var r=87;var l={en:`Kharcho`,ua:`Харчо`};var g={en:`A classic dish from Georgia, featuring beef chuck, yellow onion, garlic, white rice. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Грузія. Основні складники: яловича лопатка, жовта цибуля, часник, білий рис. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 14 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 14 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:14,i:[[`beef-chuck`,580,`g`],[`sunflower-oil`,30,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,200,`g`],[`garlic`,4,`clove`],[`tomato-paste`,70,`g`],[`sweet-paprika`,8,`g`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 60 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 60 хвилин до м’якості та готовності.`,t:[`simmering`],m:60,i:[[`white-rice`,150,`g`],[`beef-stock`,1350,`ml`],[`tkemali-sauce`,75,`g`],[`ground-coriander`,5,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`walnut`,120,`g`],[`parsley`,25,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var u={slug:i,id:n,country:`GE`,region:s,servings:4,minutes:87,title:l,text:g,steps:d};export{a as country,u as default,n as id,r as minutes,s as region,o as servings,i as slug,d as steps,g as text,l as title};